const extracted = $json.output || {};

const name = extracted.name || null;
const email = extracted.email || null;
const phone = extracted.phone || null;
const location = extracted.location || null;
const service = extracted.service || null;
const urgency = (extracted.urgency || '').toLowerCase();
const propertyType = extracted.property_type || null;
const budget = extracted.budget || null;
const intent = (extracted.intent || '').toLowerCase();

let score = 0;

if (urgency === 'high') score += 30;
else if (urgency === 'medium') score += 15;
else if (urgency === 'low') score += 5;

if (intent === 'emergency') score += 35;
else if (intent === 'ready_to_buy') score += 30;
else if (intent === 'comparison') score += 15;
else if (intent === 'research') score += 5;

if (budget) score += 15;
if (email || phone) score += 10;
if (location) score += 5;
if (service) score += 5;

score = Math.max(0, Math.min(100, score));

let status;
if (score >= 70) status = 'qualified';
else if (score >= 40) status = 'needs_review';
else status = 'unqualified';

let nextAction;
if (status === 'qualified') nextAction = 'book_appointment';
else if (status === 'needs_review') nextAction = 'human_review';
else nextAction = 'nurture_followup';

return [{
  json: {
    name, email, phone, location, service,
    urgency: urgency || null,
    property_type: propertyType,
    budget,
    intent: intent || null,
    qualification_status: status,
    qualification_score: score,
    next_action: nextAction
  }
}];

